def valid_date(y, m, d):
    import datetime
    if not (1 <= m <= 12 and 1 <= d <= 31 and 2000 <= y <= 2099):
        return False
    try:
        datetime.date(y, m, d)
        return True
    except ValueError:
        return False


def parse_dates_in_text(text):
    results = []
    for ln in text.splitlines():
        in_date_ctx = 'DATE' in ln.upper()
        for m in DATE_RE_FULL.finditer(ln):
            d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
            if valid_date(y, mo, d):
                results.append((y, mo, d, in_date_ctx))
        for m in DATE_RE_YMD.finditer(ln):
            y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
            if valid_date(y, mo, d):
                results.append((y, mo, d, in_date_ctx))
        for m in DATE_RE_SHORT.finditer(ln):
            d, mo, y2 = int(m.group(1)), int(m.group(2)), int(m.group(3))
            y = 2000 + y2
            if valid_date(y, mo, d):
                results.append((y, mo, d, in_date_ctx))
        for m in DATE_RE_MONTH.finditer(ln):
            d = int(m.group(1))
            mo_name = m.group(2)[:3].upper()
            y = int(m.group(3))
            if y < 100:
                y += 2000
            mo = MONTH_NAMES.get(mo_name)
            if mo and valid_date(y, mo, d):
                results.append((y, mo, d, in_date_ctx))
    return results


def extract_date(texts):
    all_c = []
    for t in texts:
        all_c.extend(parse_dates_in_text(t))
    if not all_c:
        return None
    labeled = [c for c in all_c if c[3]]
    pool = labeled if labeled else all_c
    cnt = Counter((y, m, d) for y, m, d, _ in pool)
    (y, m, d), _ = cnt.most_common(1)[0]
    return f"{y:04d}-{m:02d}-{d:02d}"


def process_image(path):
    img = Image.open(path)
    texts = ocr_variants(img)
    date = extract_date(texts)
    totals = [extract_total_from_text(t) for t in texts]
    totals = [t for t in totals if t is not None]
    total = Counter(totals).most_common(1)[0][0] if totals else None
    return date, total


